      SUBROUTINE INIT1CC     REINITIALIZATION WHEN NEW BEAM MATRIX IS ENCOUNTEREDCC     LIST OF COMMON BLOCKSC      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'COP.CIN'      INCLUDE 'ELM1A.CIN'      INCLUDE 'ELM1C.CIN'      INCLUDE 'ELM1D.CIN'      INCLUDE 'ELM10B.CIN'      INCLUDE 'ELM20.CIN'      INCLUDE 'SVP.CIN'CC     LOCAL VARIABLESC      INTEGER  IR2PCC---------------------------------------------------------------      IF (NV1 .GE. 1) THEN        DO 100 IR2P = 1, NV1, 1        SVP(IR2P) = .FALSE.  100   CONTINUE      ENDIF      LBEAM = .TRUE.      RECENT = .FALSE.      SOFA = .FALSE.      PSIX = 0.0      PSIY = 0.0      TOTROT = 0.0      TOTRA = 0.0      RETURN      END